-- Databricks notebook source
-- Generated by tools/generate_medallion_sql.py from the shared data dictionary.
SELECT assert_true(:catalog IN ('demo_dev', 'demo_test', 'demo_prod'), 'Invalid stage catalog');

SELECT assert_true(COUNT(*) = 0, 'Refusing to overwrite unowned demo tables')
FROM IDENTIFIER(:catalog || '.information_schema.tables')
WHERE table_schema = 'silver' AND table_name IN ('dim_product', 'dim_package', 'dim_channel', 'dim_region', 'dim_partner', 'fact_sales_monthly', 'fact_deliveries')
AND (comment IS NULL OR NOT startswith(comment, 'Managed by fabric-demo-platform demo automation'));

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.dim_product')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Illustrative beverage products.'
AS SELECT DISTINCT CAST(`sku` AS STRING) AS `sku`, CAST(`product_name` AS STRING) AS `product_name`, CAST(`product_line` AS STRING) AS `product_line`, CAST(`launch_year` AS INT) AS `launch_year`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.dim_product');

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.dim_package')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Package types, sizes and returnability; Gebinde.'
AS SELECT DISTINCT CAST(`package_code` AS STRING) AS `package_code`, CAST(`package_type` AS STRING) AS `package_type`, CAST(`volume_l` AS DOUBLE) AS `volume_l`, CAST(`returnable` AS BOOLEAN) AS `returnable`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.dim_package');

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.dim_channel')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Food retail, gastronomy, wholesale and online sales channels.'
AS SELECT DISTINCT CAST(`channel_code` AS STRING) AS `channel_code`, CAST(`channel_name` AS STRING) AS `channel_name`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.dim_channel');

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.dim_region')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Four illustrative sales regions.'
AS SELECT DISTINCT CAST(`region_code` AS STRING) AS `region_code`, CAST(`region_name` AS STRING) AS `region_name`, CAST(`sales_manager` AS STRING) AS `sales_manager`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.dim_region');

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.dim_partner')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Three fictional business partners.'
AS SELECT DISTINCT CAST(`partner_id` AS STRING) AS `partner_id`, CAST(`partner_name` AS STRING) AS `partner_name`, CAST(`partner_type` AS STRING) AS `partner_type`, CAST(`country` AS STRING) AS `country`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.dim_partner');

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.fact_sales_monthly')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Monthly sales at product/package/region/channel grain.'
AS SELECT DISTINCT CAST(`month` AS DATE) AS `month`, CAST(`sku` AS STRING) AS `sku`, CAST(`package_code` AS STRING) AS `package_code`, CAST(`region_code` AS STRING) AS `region_code`, CAST(`channel_code` AS STRING) AS `channel_code`, CAST(`actual_hl` AS DECIMAL(12,2)) AS `actual_hl`, CAST(`revenue_eur` AS DECIMAL(14,2)) AS `revenue_eur`, CAST(`margin_eur` AS DECIMAL(14,2)) AS `margin_eur`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.fact_sales_monthly');

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.silver.fact_deliveries')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Monthly partner deliveries; P-A serves NORTH and EAST.'
AS SELECT DISTINCT CAST(`month` AS DATE) AS `month`, CAST(`partner_id` AS STRING) AS `partner_id`, CAST(`sku` AS STRING) AS `sku`, CAST(`package_code` AS STRING) AS `package_code`, CAST(`region_code` AS STRING) AS `region_code`, CAST(`delivered_hl` AS DECIMAL(12,2)) AS `delivered_hl`, CAST(`on_time_pct` AS DECIMAL(5,2)) AS `on_time_pct`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.bronze.fact_deliveries');
